import{_ as t}from"./chunks/Audio.COine8Wh.js";import{_ as o}from"./chunks/Tags.BJ536pW3.js";import{c as n,o as i,j as r,G as a,ae as s,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"Emergency Conservation Program Improvement Act of 2025","description":"","frontmatter":{"legisId":"2026-07-12-emergency-conservation-program-improvement-act-of-2025","title":"Emergency Conservation Program Improvement Act of 2025","displayTitle":"Emergency Conservation Program Improvement Act of 2025","lawNumber":"119-102","billNumber":"S. 629","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ102.xml","publishDate":"2026-07-12T00:00:00-05:00","industries":["agriculture","environment"],"agencies":["Department of Agriculture"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Emergency Conservation Program Improvement Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-07-12-emergency-conservation-program-improvement-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Emergency Conservation Program Improvement Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-07-12-emergency-conservation-program-improvement-act-of-2025\\",\\"datePublished\\":\\"2026-07-12T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-07-12-emergency-conservation-program-improvement-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-07-12-emergency-conservation-program-improvement-act-of-2025.md","filePath":"congress-bills/2026-07-12-emergency-conservation-program-improvement-act-of-2025.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2026-07-12-emergency-conservation-program-improvement-act-of-2025.md"},v=Object.assign(c,{setup(m){return(d,e)=>(i(),n("div",null,[e[0]||(e[0]=r("h1",{id:"emergency-conservation-program-improvement-act-of-2025",tabindex:"-1"},[l("Emergency Conservation Program Improvement Act of 2025 "),r("a",{class:"header-anchor",href:"#emergency-conservation-program-improvement-act-of-2025","aria-label":'Permalink to "Emergency Conservation Program Improvement Act of 2025"'},"​")],-1)),a(t),a(o,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Sunday, July 12, 2026. Public Law 119-102, S. 629.</p><p><strong>Headline:</strong> The law speeds emergency conservation and forest restoration aid after farmland and private forests are damaged.</p><p><strong>Why it matters:</strong> Agricultural producers and private forest owners can receive more funding upfront and have longer to complete eligible work.</p><p><strong>What the law does:</strong></p><ul><li>Allows advance payments for urgent farmland and conservation structure replacement, repair, or restoration.</li><li>Covers up to 75 percent of replacement costs and 50 percent of repair or restoration costs in advance, as determined by the Secretary of Agriculture.</li><li>Extends the deadline for agricultural producers to use advance funds from 60 days to 180 days.</li><li>Makes certain naturally spread human-caused wildfires and federal-government-caused wildfires eligible for assistance.</li><li>Allows nonindustrial private forest owners to receive up to 75 percent of emergency measure costs in advance.</li><li>Requires private forest owners to return advance funds left unspent after 180 days within a reasonable period set by the Secretary of Agriculture.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Agricultural producers restoring damaged farmland or conservation structures.</li><li>Owners of nonindustrial private forest land undertaking emergency restoration.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Eligible farmers and private forest owners can access more money before paying the full cost of emergency work.</li><li>Recipients have up to 180 days to spend advance funds, while private forest owners must return unused money afterward.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="emergency-conservation-program-improvement-act-of-2025-1" tabindex="-1">Emergency Conservation Program Improvement Act of 2025 <a class="header-anchor" href="#emergency-conservation-program-improvement-act-of-2025-1" aria-label="Permalink to &quot;Emergency Conservation Program Improvement Act of 2025&quot;">​</a></h3><p>This law makes it easier for agricultural producers and private forest owners to receive emergency conservation and forest restoration funds before completing eligible work. It expands advance payments, allows more time to use certain funds, and clarifies that specified human-caused and federal-government-caused wildfires qualify for assistance.</p><p><strong>Key takeaways:</strong></p><ul><li>Agricultural producers may receive advance payments for urgent measures to replace or restore farmland or conservation structures.</li><li>Advance payments may cover 75 percent of replacement costs and 50 percent of repair or restoration costs, as determined by the Secretary of Agriculture.</li><li>The period for agricultural producers to use advance funds is extended from 60 days to 180 days.</li><li>Eligible wildfire damage includes damage from a non-naturally caused wildfire that spreads because of natural causes, as well as damage from a wildfire caused by the Federal Government.</li><li>Owners of nonindustrial private forest land may receive up to 75 percent of emergency measure costs in advance.</li><li>Private forest owners must return advance funds that remain unspent after 180 days within a reasonable period set by the Secretary of Agriculture.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ102.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ102.xml</a></p>',15))]))}});export{f as __pageData,v as default};
